<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';
import {usePermission} from '@/composables/permission';
import {previewSelector,type SelectorCondition,type SelectorDefinition,type SelectorPreview} from '@/api/selectors';
import SelectorConditionEditor from './SelectorConditionEditor.vue';
const props=defineProps<{disabled?:boolean}>(),emit=defineEmits<{(e:'change'):void}>(),{can}=usePermission();
const condition=ref<SelectorCondition>({junction:'AND',children:[]}),excluded=ref<SelectorCondition>({junction:'OR',children:[]}),includeText=ref(''),excludeText=ref(''),maximumCount=ref(1000),windowEnabled=ref(false),windowField=ref<'CREATED'|'STARTED'>('CREATED'),windowMode=ref<'ABSOLUTE'|'LAST_HOURS'|'PREVIOUS_DAY'|'PREVIOUS_WEEK'>('LAST_HOURS'),hours=ref(24),from=ref(''),to=ref(''),zoneId=ref('Asia/Shanghai'),mode=ref<SelectorDefinition['sampling']['mode']>('ALL'),count=ref(100),ratio=ref(0.1),seed=ref(crypto.randomUUID()),previewSize=ref(10),preview=ref<SelectorPreview>(),loading=ref(false),error=ref('');let generation=0;
const ids=(text:string)=>[...new Set(text.split(/[\s,，]+/).filter(Boolean))];
function cleaned(node:SelectorCondition):SelectorCondition|undefined{if('junction' in node){const children=node.children.map(cleaned).filter((v):v is SelectorCondition=>!!v);return children.length?{junction:node.junction,children}:undefined;}if(!node.field.trim())throw Error('条件字段不能为空');if(['IN','NOT_IN'].includes(node.operator)&&!Array.isArray(node.value))throw Error('IN / NOT_IN 的值必须是 JSON 数组');return node.operator==='EXISTS'?{field:node.field.trim(),operator:node.operator}:{...node,field:node.field.trim()};}
function definition():SelectorDefinition{if(!Number.isInteger(maximumCount.value)||maximumCount.value<1||maximumCount.value>1000)throw Error('最大任务样本数必须为 1–1000');if(!seed.value.trim()||seed.value.length>128)throw Error('请填写最多128字的抽样种子');const sampling:SelectorDefinition['sampling']={mode:mode.value,seed:seed.value.trim()};if(mode.value==='RATIO'){if(!(ratio.value>0&&ratio.value<=1))throw Error('抽样比例必须大于0且不超过1');sampling.ratio=ratio.value;}else if(mode.value!=='ALL'){if(!Number.isInteger(count.value)||count.value<1||count.value>1000)throw Error('抽样数必须为1–1000');sampling.count=count.value;}const result:SelectorDefinition={schemaVersion:'iqc-selector-v1',includeIds:ids(includeText.value),excludeIds:ids(excludeText.value),maximumCount:maximumCount.value,sampling};const filter=cleaned(condition.value),exclude=cleaned(excluded.value);if(filter)result.condition=filter;if(exclude)result.excludeCondition=exclude;if(windowEnabled.value){result.timeWindow={field:windowField.value,mode:windowMode.value,zoneId:zoneId.value.trim()};if(!result.timeWindow.zoneId)throw Error('请填写有效时区');if(windowMode.value==='ABSOLUTE'){if(!from.value||!to.value||from.value>=to.value)throw Error('请填写递增的本地 ISO 时间范围');result.timeWindow.from=from.value;result.timeWindow.to=to.value;}if(windowMode.value==='LAST_HOURS'){if(!Number.isInteger(hours.value)||hours.value<1||hours.value>8760)throw Error('最近小时数必须为1–8760');result.timeWindow.hours=hours.value;}}return JSON.parse(JSON.stringify(result));}
watch([condition,excluded,includeText,excludeText,maximumCount,windowEnabled,windowField,windowMode,hours,from,to,zoneId,mode,count,ratio,seed],()=>{++generation;preview.value=undefined;loading.value=false;error.value='';emit('change');},{deep:true});
async function runPreview(){if(props.disabled||!can('iqc:selector:preview'))return;let frozen:SelectorDefinition;try{frozen=definition();}catch(e){error.value=e instanceof Error?e.message:'选择器配置无效';return;}const ticket=++generation;loading.value=true;error.value='';preview.value=undefined;try{const data=await previewSelector(frozen,previewSize.value);if(ticket===generation)preview.value=data;}catch{if(ticket===generation)error.value='预览未获得，请核对条件、可见数据及接口权限。';}finally{if(ticket===generation)loading.value=false;}}
onBeforeUnmount(()=>++generation);defineExpose({definition});
</script>
<template><a-card size="small" title="会话选择器"><h4>包含条件</h4><SelectorConditionEditor v-model="condition" :disabled="disabled"/><h4>排除条件（优先排除）</h4><SelectorConditionEditor v-model="excluded" :disabled="disabled"/><a-form layout="vertical"><a-form-item label="显式包含会话 ID（空格或逗号分隔）"><a-textarea v-model:value="includeText" :disabled="disabled"/></a-form-item><a-form-item label="显式排除会话 ID"><a-textarea v-model:value="excludeText" :disabled="disabled"/></a-form-item><a-checkbox v-model:checked="windowEnabled" :disabled="disabled">限制时间窗口</a-checkbox><a-space v-if="windowEnabled" wrap><a-select v-model:value="windowField" :disabled="disabled" :options="[{value:'CREATED',label:'创建时间'},{value:'STARTED',label:'会话开始时间'}]" style="width:140px"/><a-select v-model:value="windowMode" :disabled="disabled" :options="[{value:'ABSOLUTE',label:'绝对时间'},{value:'LAST_HOURS',label:'最近小时'},{value:'PREVIOUS_DAY',label:'前一天'},{value:'PREVIOUS_WEEK',label:'上一周'}]" style="width:140px"/><a-input v-model:value="zoneId" :disabled="disabled" placeholder="时区" style="width:160px"/><a-input-number v-if="windowMode==='LAST_HOURS'" v-model:value="hours" :disabled="disabled" :min="1" :max="8760" :precision="0"/><template v-if="windowMode==='ABSOLUTE'"><a-input v-model:value="from" :disabled="disabled" placeholder="开始 2026-10-01T00:00:00"/><a-input v-model:value="to" :disabled="disabled" placeholder="结束 2026-10-02T00:00:00"/></template></a-space><a-form-item label="抽样策略"><a-select v-model:value="mode" :disabled="disabled" :options="[{value:'ALL',label:'全部'},{value:'FIXED_COUNT',label:'固定数量'},{value:'RATIO',label:'按比例'},{value:'RANDOM',label:'随机抽样'},{value:'EMPLOYEE_UNIFORM',label:'员工均匀'},{value:'TEAM_STRATIFIED',label:'团队分层'},{value:'RISK_PRIORITY',label:'高风险优先'}]"/><a-input-number v-if="mode==='RATIO'" v-model:value="ratio" :disabled="disabled" :min="0.000001" :max="1" :step="0.05"/><a-input-number v-else-if="mode!=='ALL'" v-model:value="count" :disabled="disabled" :min="1" :max="1000" :precision="0"/></a-form-item><a-form-item label="抽样种子（同配置可复现）"><a-input v-model:value="seed" :disabled="disabled" :maxlength="128"/></a-form-item><a-form-item label="最大任务样本数"><a-input-number v-model:value="maximumCount" :disabled="disabled" :min="1" :max="1000" :precision="0"/></a-form-item></a-form><a-space v-if="can('iqc:selector:preview')"><a-input-number v-model:value="previewSize" :disabled="disabled||loading" :min="1" :max="50" :precision="0"/><a-button :loading="loading" :disabled="disabled" @click="runPreview">预览分布与随机样本</a-button></a-space><a-alert v-if="error" type="warning" :message="error"/><template v-if="preview"><p>候选 {{preview.candidateCount}} · 命中 {{preview.matchedCount}} · 抽样 {{preview.sampledCount}} · 最终 {{preview.selectedCount}} {{preview.limited?'（已按上限截断）':''}}</p><p>时间锚点 {{preview.anchor}}；{{preview.resolvedWindow?`${preview.resolvedWindow.from} 至 ${preview.resolvedWindow.to} (${preview.resolvedWindow.zoneId})`:'未限制时间'}}</p><a-alert type="info" message="预览仅展示部分随机样本。创建任务时服务端重新计算并冻结完整选集；原请求重试复用首次快照。"/><details><summary>员工与团队分布</summary><h4>命中分布</h4><pre>{{JSON.stringify(preview.matchedDistribution,null,2)}}</pre><h4>最终分布</h4><pre>{{JSON.stringify(preview.selectedDistribution,null,2)}}</pre></details><a-table :data-source="preview.preview" row-key="conversationId" :pagination="false" :scroll="{x:700}"><a-table-column title="会话" data-index="conversationId"/><a-table-column title="文件" data-index="fileName"/><a-table-column title="员工" data-index="employeeId"/><a-table-column title="团队" data-index="employeeGroupId"/><a-table-column title="风险" data-index="riskLevel"/><a-table-column title="开始时间" data-index="startedTime"/></a-table></template></a-card></template>
<style scoped>.ant-alert{margin:10px 0}.ant-space{margin:8px 0}pre{max-height:260px;overflow:auto}</style>
